"""Generate a synchronous RTL ROM from the vendored public-domain font."""
import hashlib
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
source = ROOT / "third_party/font8x8/font8x8_basic.h"
rows = re.findall(r"\{([^{}]+)\}", source.read_text())
values = [int(value, 16) for row in rows for value in re.findall(r"0x[0-9A-Fa-f]{2}", row)]
assert len(values) == 128 * 8
lines = [
    "// Generated by sw/tools/gen_text_font.py; do not edit the bitmap data.",
    "// Daniel Hepper / Marcel Sondaar / IBM public-domain font8x8.",
    "// Source SHA256: " + hashlib.sha256(source.read_bytes()).hexdigest(),
    "`default_nettype none",
    "module text_font_rom(input wire clk, input wire [9:0] addr, output reg [7:0] row);",
    '  (* rom_style="block" *) reg [7:0] font [0:1023];',
    "  initial begin",
]
lines += [f"    font[{i}]=8'h{value:02x};" for i, value in enumerate(values)]
lines += ["  end", "  always @(posedge clk) row<=font[addr];", "endmodule", "`default_nettype wire", ""]
(ROOT / "src/rtl/video/text_font_rom.v").write_text("\n".join(lines), encoding="ascii", newline="\n")
